import { normalizeServerUrl } from '@/lib/mobile-api';

export type PairingLink = {
  serverUrl: string;
  code: string;
};

export class PairingLinkError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'PairingLinkError';
  }
}

/**
 * Parses the QR contract generated by the Server:
 * dshconnect://pair?code=...&server=https%3A%2F%2F...&v=1
 *
 * React Native's built-in URL implementation only exposes host/path for HTTP(S)
 * URLs, so custom schemes are parsed explicitly here.
 */
export function parsePairingLink(raw: string): PairingLink {
  const value = raw.trim();
  if (!value) {
    throw new PairingLinkError('二维码内容为空。');
  }
  if (!/^dshconnect:/i.test(value)) {
    throw new PairingLinkError('二维码不是 DSH Connect 配对链接。');
  }

  const withoutScheme = value.slice('dshconnect:'.length).replace(/^\/+/, '');
  const queryStart = withoutScheme.indexOf('?');
  const hashStart = withoutScheme.indexOf('#');
  const pathEnd = [queryStart, hashStart]
    .filter((index) => index >= 0)
    .reduce((smallest, index) => Math.min(smallest, index), withoutScheme.length);
  const route = withoutScheme.slice(0, pathEnd).replace(/\/+$/, '');
  if (route !== 'pair') {
    throw new PairingLinkError('二维码不是手机配对链接。');
  }

  const query = queryStart >= 0
    ? withoutScheme.slice(queryStart + 1).split('#')[0]
    : '';
  const queryParams = new URLSearchParams(query);
  const version = queryParams.get('v');
  const code = queryParams.get('code')?.trim() ?? '';
  const server = queryParams.get('server')?.trim() ?? '';
  return pairingFromParts(server, code, version);
}

export function pairingFromParts(
  rawServer: string | null | undefined,
  rawCode: string | null | undefined,
  version?: string | null,
): PairingLink {
  if (version !== null && version !== undefined && version !== '1') {
    throw new PairingLinkError('二维码协议版本不受支持，请升级 App。');
  }

  const code = rawCode?.trim() ?? '';
  if (!code || code.length > 128 || /[\r\n\x00]/.test(code)) {
    throw new PairingLinkError('缺少有效的配对码。');
  }

  const server = rawServer?.trim() ?? '';
  if (!server) {
    throw new PairingLinkError('缺少 Server 地址。');
  }

  try {
    return {
      serverUrl: normalizeServerUrl(server),
      code: code.toUpperCase(),
    };
  } catch (error) {
    throw new PairingLinkError(error instanceof Error ? error.message : 'Server 地址无效。');
  }
}
